bits.write(0,6).write(1,16).write(0,5).write(0,2).write(7,4); // one floor, endpoints only
bits.write(0,6).write(1,16).write(0,24).write(32,24).write(0,24).write(0,6).write(0,8).write(1,3).write(0,1).write(1,8); // one residue
